class Solution {
public:
    int findMaxValueOfEquation(vector<vector<int>>& points, int k) {
        int n = points.size();
        deque<int> dq;
        long long ans = LLONG_MIN;
        for (int j = 0; j < n; j++) {
            long long xj = points[j][0], yj = points[j][1];
            while (!dq.empty() && points[dq.front()][0] < xj - k) {
                dq.pop_front();
            }
            if (!dq.empty()) {
                int i = dq.front();
                long long val = ((long long)points[i][1] - points[i][0]) + (yj + xj);
                if (val > ans) ans = val;
            }
            long long cur = yj - xj;
            while (!dq.empty() && ((long long)points[dq.back()][1] - points[dq.back()][0]) <= cur) {
                dq.pop_back();
            }
            dq.push_back(j);
        }
        return (int)ans;
    }
};
